1	export interface Customer {
2	  yearsWithMHPCO: number;
3	}
4	
5	export interface Item {
6	  type: string;
7	  material?: string;
8	  enchantment?: number;
9	  cursed?: boolean;
10	}
11	
12	export interface QuoteStep {
13	  op: "quote";
14	  items: Item[];
15	}
16	
17	export interface Damage {
18	  itemType: string;
19	  amount: number;
20	}
21	
22	export interface Incident {
23	  cause: string;
24	  damages: Damage[];
25	}
26	
27	export interface ClaimStep {
28	  op: "claim";
29	  policy: number;
30	  incident: Incident;
31	}
32	
33	export type Step = QuoteStep | ClaimStep;
34	
35	export interface Scenario {
36	  customer: Customer;
37	  steps: Step[];
38	}
39	
40	export interface QuoteResult {
41	  premium: number;
42	}
43	
44	export interface ClaimResult {
45	  payout: number;
46	  remainingCap: number;
47	}
48	
49	export type StepResult = QuoteResult | ClaimResult;
50	
51	export interface ScenarioResult {
52	  results: StepResult[];
53	}
54	
55	const PROCESSING_FEE = 5;
56	const BASE_PREMIUMS: Record<string, number> = {
57	  sword: 100,
58	  amulet: 60,
59	  staff: 80,
60	  potion: 40,
61	  rune: 25,
62	  moonstone: 25,
63	};
64	
65	const BLOCK_SIZE = 3;
66	const BLOCK_PREMIUM = 60;
67	
68	const isBlock = (sameTypeItems: Item[]): boolean =>
69	  sameTypeItems.length === BLOCK_SIZE;
70	
71	const rejectUnknownItemType = (type: string): never => {
72	  throw new Error(`Unknown item type: ${type}`);
73	};
74	
75	const basePremiumOfItem = (item: Item): number =>
76	  BASE_PREMIUMS[item.type] ?? rejectUnknownItemType(item.type);
77	
78	const sumOverItems = (items: Item[], valueOfItem: (item: Item) => number) =>
79	  items.reduce((sum, item) => sum + valueOfItem(item), 0);
80	
81	const sumOfItemBasePremiums = (items: Item[]): number =>
82	  sumOverItems(items, basePremiumOfItem);
83	
84	const groupByType = (items: Item[]): Item[][] =>
85	  Object.values(
86	    items.reduce<Record<string, Item[]>>(
87	      (groups, item) => ({
88	        ...groups,
89	        [item.type]: [...(groups[item.type] ?? []), item],
90	      }),
91	      {},
92	    ),
93	  );
94	
95	const basePremiumOfGroup = (items: Item[]): number =>
96	  isBlock(items) ? BLOCK_PREMIUM : sumOfItemBasePremiums(items);
97	
98	const policyBasePremium = (items: Item[]): number =>
99	  groupByType(items).reduce((sum, group) => sum + basePremiumOfGroup(group), 0);
100	
101	const CURSED_SURCHARGE_RATE = 0.5;
102	const HIGH_ENCHANTMENT_SURCHARGE_RATE = 0.3;
103	
104	const HIGH_ENCHANTMENT_THRESHOLD = 5;
105	
106	const isCursed = (item: Item): boolean => item.cursed === true;
107	
108	const UNENCHANTED = 0;
109	
110	const enchantmentOf = (item: Item): number => item.enchantment ?? UNENCHANTED;
111	
112	const isHighlyEnchanted = (item: Item): boolean =>
113	  enchantmentOf(item) >= HIGH_ENCHANTMENT_THRESHOLD;
114	
115	const NO_SURCHARGE_RATE = 0;
116	
117	const surchargeRateOfItem = (item: Item): number =>
118	  (isCursed(item) ? CURSED_SURCHARGE_RATE : NO_SURCHARGE_RATE) +
119	  (isHighlyEnchanted(item)
120	    ? HIGH_ENCHANTMENT_SURCHARGE_RATE
121	    : NO_SURCHARGE_RATE);
122	
123	const surchargeOfItem = (item: Item): number =>
124	  basePremiumOfItem(item) * surchargeRateOfItem(item);
125	
126	const sumOfItemSurcharges = (items: Item[]): number =>
127	  sumOverItems(items, surchargeOfItem);
128	
129	const FIRST_INSURANCE_SURCHARGE_RATE = 0.1;
130	
131	const firstInsuranceSurcharge = (basePremium: number): number =>
132	  basePremium * FIRST_INSURANCE_SURCHARGE_RATE;
133	
134	const roundPremiumInMHPCOsFavour = (premium: number): number =>
135	  Math.ceil(premium);
136	
137	const LOYALTY_DISCOUNT_RATE = 0.2;
138	const LOYALTY_YEARS_THRESHOLD = 2;
139	const NO_DISCOUNT = 0;
140	
141	const isLoyal = (customer: Customer): boolean =>
142	  customer.yearsWithMHPCO >= LOYALTY_YEARS_THRESHOLD;
143	
144	const loyaltyDiscount = (customer: Customer, basePremium: number): number =>
145	  isLoyal(customer) ? basePremium * LOYALTY_DISCOUNT_RATE : NO_DISCOUNT;
146	
147	const FOLLOW_UP_CONTRACT_DISCOUNT_RATE = 0.15;
148	
149	const isFollowUpContract = (previousQuoteCount: number): boolean =>
150	  previousQuoteCount > 0;
151	
152	const followUpContractDiscount = (
153	  previousQuoteCount: number,
154	  basePremium: number,
155	): number =>
156	  isFollowUpContract(previousQuoteCount)
157	    ? basePremium * FOLLOW_UP_CONTRACT_DISCOUNT_RATE
158	    : NO_DISCOUNT;
159	
160	const quote = (
161	  items: Item[],
162	  customer: Customer,
163	  previousQuoteCount: number,
164	): QuoteResult => {
165	  const basePremium = policyBasePremium(items);
166	  const surcharges =
167	    sumOfItemSurcharges(items) + firstInsuranceSurcharge(basePremium);
168	  const discounts =
169	    loyaltyDiscount(customer, basePremium) +
170	    followUpContractDiscount(previousQuoteCount, basePremium);
171	  return {
172	    premium: roundPremiumInMHPCOsFavour(
173	      PROCESSING_FEE + basePremium + surcharges - discounts,
174	    ),
175	  };
176	};
177	
178	const DEDUCTIBLE = 100;
179	const INSURANCE_VALUES: Record<string, number> = {
180	  sword: 1000,
181	  amulet: 600,
182	  rune: 250,
183	};
184	const CAP_FACTOR = 2;
185	
186	const HALF_REIMBURSEMENT_ENCHANTMENT_THRESHOLD = 8;
187	const HALF_REIMBURSEMENT_RATE = 0.5;
188	const FULL_REIMBURSEMENT_RATE = 1;
189	
190	const rejectItemNotInPolicy = (type: string): never => {
191	  throw new Error(`Item not insured by this policy: ${type}`);
192	};
193	
194	const damagedItem = (damage: Damage, availableItems: Item[]): Item =>
195	  availableItems.find((item) => item.type === damage.itemType) ??
196	  rejectItemNotInPolicy(damage.itemType);
197	
198	const isDeeplyEnchanted = (item: Item): boolean =>
199	  enchantmentOf(item) >= HALF_REIMBURSEMENT_ENCHANTMENT_THRESHOLD;
200	
201	const reimbursementRateOfItem = (item: Item): number =>
202	  isDeeplyEnchanted(item) ? HALF_REIMBURSEMENT_RATE : FULL_REIMBURSEMENT_RATE;
203	
204	const rejectNegativeDamageAmount = (amount: number): never => {
205	  throw new Error(`Negative damage amount: ${amount}`);
206	};
207	
208	const damagedAmount = (damage: Damage): number =>
209	  damage.amount >= 0 ? damage.amount : rejectNegativeDamageAmount(damage.amount);
210	
211	const payoutOfDamage = (damage: Damage, item: Item): number =>
212	  damagedAmount(damage) * reimbursementRateOfItem(item) - DEDUCTIBLE;
213	
214	const withoutItem = (items: Item[], item: Item): Item[] =>
215	  items.filter((candidate) => candidate !== item);
216	
217	interface ClaimedDamage {
218	  damage: Damage;
219	  item: Item;
220	}
221	
222	const assignDistinctItems = (
223	  damages: Damage[],
224	  policyItems: Item[],
225	): ClaimedDamage[] =>
226	  damages.reduce<{ claimed: ClaimedDamage[]; unclaimed: Item[] }>(
227	    ({ claimed, unclaimed }, damage) => {
228	      const item = damagedItem(damage, unclaimed);
229	      return {
230	        claimed: [...claimed, { damage, item }],
231	        unclaimed: withoutItem(unclaimed, item),
232	      };
233	    },
234	    { claimed: [], unclaimed: policyItems },
235	  ).claimed;
236	
237	const payoutOfIncident = (incident: Incident, policyItems: Item[]): number =>
238	  assignDistinctItems(incident.damages, policyItems).reduce(
239	    (sum, { damage, item }) => sum + payoutOfDamage(damage, item),
240	    0,
241	  );
242	
243	const insuredValueOfItem = (item: Item): number => INSURANCE_VALUES[item.type];
244	
245	const insuranceSum = (items: Item[]): number =>
246	  sumOverItems(items, insuredValueOfItem);
247	
248	const capOfPolicy = (policyItems: Item[]): number =>
249	  CAP_FACTOR * insuranceSum(policyItems);
250	
251	const roundPayoutInMHPCOsFavour = (payout: number): number =>
252	  Math.floor(payout);
253	
254	const claim = (
255	  incident: Incident,
256	  policyItems: Item[],
257	  availableCap: number,
258	): ClaimResult => {
259	  const payout = roundPayoutInMHPCOsFavour(
260	    Math.min(payoutOfIncident(incident, policyItems), availableCap),
261	  );
262	  return {
263	    payout,
264	    remainingCap: availableCap - payout,
265	  };
266	};
267	
268	const isQuoteStep = (step: Step): step is QuoteStep => step.op === "quote";
269	
270	const quoteSteps = (steps: Step[]): QuoteStep[] => steps.filter(isQuoteStep);
271	
272	const insuredItemsOfPolicy = (steps: Step[], policy: number): Item[] =>
273	  quoteSteps(steps)[policy].items;
274	
275	const quoteCountBefore = (steps: Step[], stepIndex: number): number =>
276	  quoteSteps(steps.slice(0, stepIndex)).length;
277	
278	type RemainingCaps = Record<number, number>;
279	
280	const availableCapOfPolicy = (
281	  remainingCaps: RemainingCaps,
282	  policyItems: Item[],
283	  policy: number,
284	): number => remainingCaps[policy] ?? capOfPolicy(policyItems);
285	
286	export const runScenario = (scenario: Scenario): ScenarioResult => {
287	  const remainingCaps: RemainingCaps = {};
288	  const results = scenario.steps.map((step, stepIndex) => {
289	    if (isQuoteStep(step)) {
290	      return quote(
291	        step.items,
292	        scenario.customer,
293	        quoteCountBefore(scenario.steps, stepIndex),
294	      );
295	    }
296	    const policyItems = insuredItemsOfPolicy(scenario.steps, step.policy);
297	    const result = claim(
298	      step.incident,
299	      policyItems,
300	      availableCapOfPolicy(remainingCaps, policyItems, step.policy),
301	    );
302	    remainingCaps[step.policy] = result.remainingCap;
303	    return result;
304	  });
305	  return { results };
306	};
